import { SingletonProto, AccessLevel, Inject } from 'egg';

@SingletonProto({ accessLevel: AccessLevel.PUBLIC })
export class OrderService {
  @Inject()
  private logger: any;

  async createOrder(data: any) {
    const order = { id: Date.now(), ...data };
    // 请求返回后异步记录日志
    setTimeout(async () => {
      this.logger.info('Order created:', order.id);
      await this.sendNotification(order);
    }, 0);
    return order;
  }

  private async sendNotification(order: any) {
    // 发送通知
  }
}

import { SingletonProto, AccessLevel, Inject } from 'egg';

@SingletonProto({ accessLevel: AccessLevel.PUBLIC })
export class CacheService {
  @Inject()
  private redisService: any;

  async getData(key: string) {
    const data = await this.redisService.get(key);
    if (!data) {
      const fresh = await this.fetchFromDB(key);
      // 异步回写缓存，不阻塞响应
      setTimeout(async () => {
        await this.redisService.set(key, fresh, 3600);
      }, 0);
      return fresh;
    }
    return data;
  }

  private async fetchFromDB(key: string) {
    return { key, value: 'from-db' };
  }
}

import { SingletonProto, AccessLevel, Inject, BackgroundTaskHelper } from 'egg';

@SingletonProto({ accessLevel: AccessLevel.PUBLIC })
export class ReportService {
  @Inject()
  private backgroundTaskHelper: BackgroundTaskHelper;

  async generateReport(data: any) {
    this.backgroundTaskHelper.run(async () => {
      // 这里可能会抛异常
      const result = await this.callExternalAPI(data);
      await this.saveReport(result);
    });
    return { status: 'processing' };
  }

  private async callExternalAPI(data: any) {
    throw new Error('API timeout');
  }

  private async saveReport(result: any) {}
}
